import type { AgentsConfig, SpokeDefinitionId } from '@qa-ai-stlc/schemas';

/** Marks a subagent file the engine wrote, so a later run only ever overwrites its own output. */
export const GENERATED_SUBAGENT_MARKER =
  '<!-- Generated by "qa agents generate" from agents.models in .qa/config.yaml. Change the config and run it again; edits here are not kept. -->';

export const SUBAGENT_DIRECTORY = '.claude/agents';

interface SpokeSubagentBase {
  readonly id: SpokeDefinitionId;
  /** Read by the host to decide when to delegate, so it states when the hub dispatches the spoke. */
  readonly description: string;
  readonly task: string;
  readonly payload: string;
  /**
   * Host tools the subagent never gets, written into its `disallowedTools`. A subagent otherwise
   * inherits every tool of the session, so a rule that depends on what it cannot reach has to
   * remove the tools that reach it; the engine's own (MCP) tools stay.
   */
  readonly disallowedTools?: readonly string[];
}

// How the work is done: by a plugin skill, or, for a spoke that has none, by rules written out here.
type SpokeSubagentDefinition = SpokeSubagentBase &
  ({ readonly skill: string } | { readonly guidance: readonly string[] });

