export interface GeneratedSubagent {
  readonly spokeId: SpokeDefinitionId;
  /** Project-relative, with `/` separators. */
  readonly path: string;
  readonly content: string;
  /** Absent when the spoke has no configured model and so inherits the session's. */
  readonly model?: string;
}

function subagentName(id: SpokeDefinitionId): string {
  return id.startsWith('qa-') ? id : `qa-${id}`;
}

function renderSubagent(definition: SpokeSubagentDefinition, model: string | undefined): GeneratedSubagent {
  const name = subagentName(definition.id);
  const lines = [
    '---',
    `name: ${name}`,
    // A quoted scalar, so a colon in the text cannot end the value early.
    `description: ${JSON.stringify(definition.description)}`,
    ...(model === undefined ? [] : [`model: ${model}`]),
    ...(definition.disallowedTools === undefined
      ? []
      : [`disallowedTools: ${definition.disallowedTools.join(', ')}`]),
    '---',
    '',
    GENERATED_SUBAGENT_MARKER,
    '',
    `You are the \`${definition.id}\` spoke of the QA-AI-STLC hub. The hub gives you one task: ${definition.task}.`,
    '',
    ...('skill' in definition
      ? [`- Load the \`${definition.skill}\` skill and follow it for how the work is done.`]
      : definition.guidance.map((line) => `- ${line}`)),
    '- Work only from that task and from what engine tools (`qa.*`) return. Reach the application under test only through engine tools.',
    '- Never talk to the operator, approve a gate or call another spoke: the hub does that.',
    '- Finish with one JSON value and nothing after it: `{ "schemaVersion": 1, "spokeId", "taskId", "status": "ok", "payload" }`, or `status: "error"` with `error: { "code", "message" }` when you could not do the task. Use the `spokeId` and `taskId` the hub gave you.',
    `- The payload is ${definition.payload}. The hub checks it against the engine, so do not claim anything the engine did not record.`,
    '',
  ];
  return {
    spokeId: definition.id,
    path: `${SUBAGENT_DIRECTORY}/${name}.md`,
    content: lines.join('\n'),
    ...(model === undefined ? {} : { model }),
  };
}

/** One Claude Code subagent per spoke definition, with the `model:` the config routes it to. */
export function renderSpokeSubagents(models: AgentsConfig['models']): readonly GeneratedSubagent[] {
  return SPOKE_SUBAGENT_DEFINITIONS.map((definition) => renderSubagent(definition, models[definition.id]));
}

export function listSpokeDefinitionIds(): readonly SpokeDefinitionId[] {
  return SPOKE_SUBAGENT_DEFINITIONS.map((definition) => definition.id);
}
